'use strict';
(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.ReikaHeadRig=api;})(typeof globalThis!=='undefined'?globalThis:this,function(){
const clamp=(value,min,max)=>Math.max(min,Math.min(max,Number(value)||0));
function pose(input={}){return {yaw:clamp(input.yaw,-30,30),pitch:clamp(input.pitch,-20,20),roll:clamp(input.roll,-20,20),gazeX:clamp(input.gazeX,-12,12),gazeY:clamp(input.gazeY,-10,10)};}
function transform(p){p=pose(p);return 'translate('+(p.yaw*.48).toFixed(2)+' '+(p.pitch*.35).toFixed(2)+') rotate('+p.roll.toFixed(2)+' 400 260) scale('+(1-Math.abs(p.yaw)*.004).toFixed(4)+' 1)';}
function mount(){const svg=document.getElementById('reika'),panel=document.querySelector('.panel');if(!svg||!panel)return;
const ns='http://www.w3.org/2000/svg',groups=['hairBack','ears','head','hairFront'],wrappers={};
for(const id of groups){const element=document.getElementById(id);if(!element)continue;const outer=document.createElementNS(ns,'g');outer.setAttribute('data-head-rig',id);element.parentNode.insertBefore(outer,element);outer.appendChild(element);wrappers[id]=outer;}
const eyes=Array.from(svg.querySelectorAll('#head .eyes ellipse')).filter(e=>e.getAttribute('fill')==='#204a87');const pupils=Array.from(svg.querySelectorAll('#head .eyes circle'));
const section=document.createElement('section');section.className='head-rig-tools';section.innerHTML='<h3>Живая голова Рэйки · собственный 2D-риг</h3><label for="headYaw">Поворот влево / вправо</label><input id="headYaw" type="range" min="-30" max="30" value="0"><label for="headPitch">Наклон вверх / вниз</label><input id="headPitch" type="range" min="-20" max="20" value="0"><label for="headRoll">Наклон головы</label><input id="headRoll" type="range" min="-20" max="20" value="0"><label for="headGazeX">Взгляд по горизонтали</label><input id="headGazeX" type="range" min="-12" max="12" value="0"><label for="headGazeY">Взгляд по вертикали</label><input id="headGazeY" type="range" min="-10" max="10" value="0"><label><input id="headPointer" type="checkbox"> Следить взглядом за указателем</label><button id="headCenter" type="button">Вернуть голову в центр</button><p id="headRigStatus" role="status">Рабочий SVG-риг без Cubism. Моргание, рот и хвосты используют существующие контроллеры.</p>';panel.append(section);
const $=id=>section.querySelector('#'+id),ids=['Yaw','Pitch','Roll','GazeX','GazeY'];let current=pose(),target=pose(),pointer=false;
function read(){return pose({yaw:Number($('headYaw').value),pitch:Number($('headPitch').value),roll:Number($('headRoll').value),gazeX:Number($('headGazeX').value),gazeY:Number($('headGazeY').value)});}
function apply(){const t=transform(current);for(const [id,el] of Object.entries(wrappers)){if(id==='hairBack')el.setAttribute('transform','translate('+(current.yaw*.18).toFixed(2)+' 0) rotate('+(current.roll*.6).toFixed(2)+' 400 260)');else el.setAttribute('transform',t);}for(const eye of eyes)eye.setAttribute('transform','translate('+current.gazeX.toFixed(2)+' '+current.gazeY.toFixed(2)+')');for(const circle of pupils)circle.setAttribute('transform','translate('+current.gazeX.toFixed(2)+' '+current.gazeY.toFixed(2)+')');}
function update(){target=read();apply();}for(const id of ids)$('head'+id).addEventListener('input',update);
$('headCenter').onclick=()=>{for(const id of ids)$('head'+id).value='0';target=pose();current=pose();apply();};
$('headPointer').onchange=()=>{pointer=$('headPointer').checked;};
svg.addEventListener('pointermove',event=>{if(!pointer)return;const box=svg.getBoundingClientRect();if(!box.width||!box.height)return;const x=(event.clientX-box.left)/box.width-.5,y=(event.clientY-box.top)/box.height-.5;$('headGazeX').value=String(Math.round(clamp(x*24,-12,12)));$('headGazeY').value=String(Math.round(clamp(y*20,-10,10)));target=read();});
const reduced=window.matchMedia('(prefers-reduced-motion: reduce)');let raf=0,last=null;
function tick(ts){const dt=last===null?0:Math.min((ts-last)/1000,.05);last=ts;const factor=reduced.matches?1:1-Math.exp(-dt*12);for(const key of Object.keys(current))current[key]+=(target[key]-current[key])*factor;apply();raf=requestAnimationFrame(tick);}raf=requestAnimationFrame(tick);window.addEventListener('pagehide',()=>cancelAnimationFrame(raf),{once:true});apply();return {get pose(){return {...current};},get target(){return {...target};},setPose(v){const p=pose(v);for(const [key,id] of [['yaw','Yaw'],['pitch','Pitch'],['roll','Roll'],['gazeX','GazeX'],['gazeY','GazeY']])$('head'+id).value=String(p[key]);target=p;current=p;apply();}};}
return {pose,transform,mount};
});
if(typeof window!=='undefined')window.ReikaHeadRigController=window.ReikaHeadRig.mount();
